import{_ as o,o as r,c as n,ah as s}from"./chunks/framework.DjU4PSOm.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"인심(人心)과 도심(道心)이란?","slug":"인심-人心-과-도심-道心-이란","link":"#인심-人心-과-도심-道心-이란","children":[]},{"level":2,"title":"논쟁의 배경 인물: 이이와 성혼","slug":"논쟁의-배경-인물-이이와-성혼","link":"#논쟁의-배경-인물-이이와-성혼","children":[]},{"level":2,"title":"논쟁의 발단","slug":"논쟁의-발단","link":"#논쟁의-발단","children":[]},{"level":2,"title":"성혼의 입장: 퇴계의 호발설은 정당하다","slug":"성혼의-입장-퇴계의-호발설은-정당하다","link":"#성혼의-입장-퇴계의-호발설은-정당하다","children":[]},{"level":2,"title":"이이의 반박: 인심도심과 사단칠정은 다른 맥락의 개념이다","slug":"이이의-반박-인심도심과-사단칠정은-다른-맥락의-개념이다","link":"#이이의-반박-인심도심과-사단칠정은-다른-맥락의-개념이다","children":[]},{"level":2,"title":"논쟁의 전개와 핵심 개념들","slug":"논쟁의-전개와-핵심-개념들","link":"#논쟁의-전개와-핵심-개념들","children":[]},{"level":2,"title":"결론","slug":"결론","link":"#결론","children":[]}],"relativePath":"philosophy/Korean-Philosophy/10. 인심도심 논쟁.md","filePath":"philosophy/Korean-Philosophy/10. 인심도심 논쟁.md"}'),e={name:"philosophy/Korean-Philosophy/10. 인심도심 논쟁.md"};function a(l,t,g,i,u,h){return r(),n("div",null,[...t[0]||(t[0]=[s('<h2 id="인심-人心-과-도심-道心-이란" tabindex="-1">인심(人心)과 도심(道心)이란? <a class="header-anchor" href="#인심-人心-과-도심-道心-이란" aria-label="Permalink to &quot;인심(人心)과 도심(道心)이란?&quot;">​</a></h2><p>&#39;인심도심&#39;설은 주자학의 정수로 여겨진 개념이다. 주희는 이를 요임금·순임금·우임금이 서로 전한 &#39;도(道)&#39;로 평가했는데, 근거는 『서경』 「대우모」의 16자 심법(心法) — &quot;<strong>人心惟危 道心惟微 惟精惟一 允執厥中</strong>&quot;(사람의 마음은 오직 위태로우며 도덕적 마음은 오직 은미하다. 오직 집중하고 오직 한결같이 유지하여 참으로 그 가운데를 잡아라) — 이다.</p><p>주희는 『중용장구서』에서 다음과 같이 설명한다 — &quot;마음의 허령지각(虛靈知覺)은 하나일 뿐이다. 하지만 인심과 도심의 차이가 있다고 말하는 것은, 하나는 <strong>&#39;형기의 사사로움에서 생겨나고&#39;</strong>(生於形氣之私) 다른 하나는 <strong>&#39;성명의 올바른 것에서 기원하여&#39;</strong>(原於性命之正) 지각하는 것이 같지 않기 때문이다.&quot; 인간은 형기를 갖지 않은 자가 없으므로 아무리 지혜로운 사람이라도 인심이 없을 수 없고, 인성을 갖지 않은 사람이 없으므로 아무리 어리석은 사람이라도 도심이 없을 수 없다 — 두 마음은 늘 뒤섞여 있으며, 이를 잘 다스리지 못하면 위태로운 것은 더욱 위태로워지고 은미한 것은 더욱 은미해져 천리(도심)가 인욕(인심)의 사사로움을 이기지 못하게 된다.</p><p>정리하면 <strong>도심</strong>은 성명의 올바름에서 기원한 도덕적 마음(천리의 공정함)으로, 확충의 대상이며 은미하다. <strong>인심</strong>은 형기의 사사로움에서 생겨난 생리적 욕구에 따른 마음으로, 절제·통제의 대상이며 위태롭고 불안하다. 단, 인심이 곧 인욕(人欲)은 아니다 — 인심 자체는 가치중립적이며, 다만 절제되지 않으면 인욕으로 흐르기 쉬울 뿐이다. 주희의 결론은 &quot;<strong>도심을 확충하고 인심을 절제하는 삶을 살자</strong>&quot;는 것이다.</p><h2 id="논쟁의-배경-인물-이이와-성혼" tabindex="-1">논쟁의 배경 인물: 이이와 성혼 <a class="header-anchor" href="#논쟁의-배경-인물-이이와-성혼" aria-label="Permalink to &quot;논쟁의 배경 인물: 이이와 성혼&quot;">​</a></h2><p><strong>이이(율곡, 1536~1584)</strong>는 어려서부터 총명했고 16세에 어머니를 잃은 후 방황하다 금강산에서 불서를 탐독하기도 했음(삭발은 하지 않은 거사 수행). 하산 후 성혼과 도의지교를 맺음. 9번의 과거에서 장원해 &#39;구도장원공&#39;으로 불렸으며, 퇴계 이황을 직접 만나 학문적 대화를 나눈 바 있음. <strong>성혼(우계, 1535~1598)</strong>은 백인걸 문하에서 수학했고, 1568년 퇴계를 직접 뵙고 가르침을 받은 바 있으며 1572년 이이와 사단칠정·리기설을 논함. 이후 이이 사후 서인의 영수로 활동함.</p><h2 id="논쟁의-발단" tabindex="-1">논쟁의 발단 <a class="header-anchor" href="#논쟁의-발단" aria-label="Permalink to &quot;논쟁의 발단&quot;">​</a></h2><p>1572년 여름, 성혼(37세)이 이이에게 편지를 보내면서 논쟁이 시작됨. 성혼은 원래 퇴계의 <strong>리기호발설</strong>(理氣互發說, 사단은 리가 발함, 칠정은 기가 발함)에 의문을 품고 있었으나, 주희의 &#39;인심도심설&#39;에서 &quot;성명의 바른 데에 근원을 두기도 하고, 형기의 사사로움에서 생기기도 한다&quot;는 논의를 읽고 이것이 퇴계의 말씀과 은연중 부합한다고 느껴 퇴계의 설을 지지하는 쪽으로 생각을 바꾸었음을 밝히며 이이에게 의견을 구함. 이로부터 두 사람은 9통의 편지를 주고받으며 논쟁을 전개함(3서 이후 성혼의 편지는 일부만 전함).</p><h2 id="성혼의-입장-퇴계의-호발설은-정당하다" tabindex="-1">성혼의 입장: 퇴계의 호발설은 정당하다 <a class="header-anchor" href="#성혼의-입장-퇴계의-호발설은-정당하다" aria-label="Permalink to &quot;성혼의 입장: 퇴계의 호발설은 정당하다&quot;">​</a></h2><p>성혼은 이황의 「심통성정도」에 나오는 다음 구절을 근거로 든다 — &quot;사단은 리가 발함에 기가 따른 것(<strong>理發而氣隨之</strong>)으로 본래 순선(純善)하여 악이 없다… 칠정은 기가 발함에 리가 탄 것(<strong>氣發而理乘之</strong>)으로 이것 역시 불선함이 없지만 기가 발하여 절도에 맞지 않아서 리를 멸하게 되면 방종하여 악이 된다.&quot;</p><p>성혼은 인심도심과 사단칠정을 <strong>&#39;소종래&#39;(所從來, 근원)</strong>의 관점에서 연결한다. 도심은 &#39;성명의 바름에서 근원함&#39;(原於性命之正) — <strong>주리(主理)</strong>이고, 인심은 &#39;형기의 사사로움에서 생김&#39;(生於形氣之私) — <strong>주기(主氣)</strong>이다. 이 구도를 사단칠정에 그대로 적용하면, 도심=사단, 인심=칠정으로 볼 수 있고, 결국 &quot;사단을 발어리(發於理), 칠정을 발어기(發於氣)&quot;로 표현하는 것도 자연스럽다. 즉 <strong>리기의 호발</strong>(互發)은 천하의 정해진 이치이므로 퇴계의 견해는 정당하다는 것.</p><h2 id="이이의-반박-인심도심과-사단칠정은-다른-맥락의-개념이다" tabindex="-1">이이의 반박: 인심도심과 사단칠정은 다른 맥락의 개념이다 <a class="header-anchor" href="#이이의-반박-인심도심과-사단칠정은-다른-맥락의-개념이다" aria-label="Permalink to &quot;이이의 반박: 인심도심과 사단칠정은 다른 맥락의 개념이다&quot;">​</a></h2><p>이이는 세 가지로 반박한다. 첫째, <strong>맥락이 다르다</strong> — 인심도심은 생성된 마음의 <strong>근원</strong>을 따져보는 맥락에서 나온 것이고, 사단칠정은 감정의 <strong>생성 과정</strong>에 주목한 것이다. 그래서 인심도심은 <strong>대립 관계</strong>로 볼 수 있지만(도심이면 인심이 아니고, 인심이면 도심이 아님), 사단칠정은 <strong>포함 관계</strong>다 — 칠정은 사단을 포함하지만 사단은 칠정을 포함할 수 없다(&quot;칠정 중에서 선한 부분만을 사단이라 이름한 것&quot;). 둘째, 주자가 &quot;사단은 리의 발, 칠정은 기의 발&quot;이라 말한 것은 대강을 표현한 말일 뿐이며, 도심은 성명(주리), 인심은 형기(주기) 측면으로 해석할 수 있다. 셋째, 마음의 구조(심-성-정-의) 자체가 호발을 허용하지 않는다 — 발현의 <strong>주체는 기</strong>이고 <strong>원리는 리</strong>이며, 발함에 있어 &#39;기의 개입&#39;(氣之用事) 여부에 따라 도심과 인심으로 나뉠 뿐, 마음의 근원은 하나이고 발생 경로도 하나다.</p><p>이이의 핵심 명제는 <strong>&quot;기발리승일도설&quot;</strong>(氣發理乘一途說) — 감정의 발현은 언제나 기가 본성(리)을 드러내는 하나의 길뿐이며, 사단이든 칠정이든 예외 없이 &#39;기발리승&#39;의 경로를 밟는다는 것이다. &quot;성이 발하여 정이 된다&quot;(性發爲情)는 관점에서 볼 때 모든 감정은 리(성)가 발현된 것이므로 본래 선하다. 다만 발현의 주체인 <strong>기에 맑음과 탁함의 편차</strong>가 있어서, 맑은 기는 리(천리)를 그대로 드러내지만 탁한 기는 리를 온전히 드러내지 못해 결국 악한 감정이 생성된다. 따라서 <strong>&quot;악한 감정이 악한 것은 천리의 잘못이 아니라 그것을 제대로 드러내지 못한 탁한 기질의 잘못&quot;</strong>이며, 선한 감정과 악한 감정 모두 그 뿌리(소종래)는 동일한 천리에 있다는 것이 이이의 결론이다.</p><h2 id="논쟁의-전개와-핵심-개념들" tabindex="-1">논쟁의 전개와 핵심 개념들 <a class="header-anchor" href="#논쟁의-전개와-핵심-개념들" aria-label="Permalink to &quot;논쟁의 전개와 핵심 개념들&quot;">​</a></h2><p>두 사람은 이후 여러 차례 편지를 주고받으며 다음 개념들을 정교화한다.</p><ul><li><strong>리기지묘(理氣之妙)</strong>: 리와 기는 &quot;하나이면서 둘이고, 둘이면서 하나&quot;다 — 존재론적으로는 하나(리기불상리)이지만 역할에는 분명한 차이가 있다(리는 주재자, 기는 구현자). <strong>리일분수</strong>에서 &#39;분수&#39;는 기에 의해 결정되므로, 리는 보편성의 원리이고 기는 개별성의 원리다.</li><li><strong>리통기국(理通氣局)</strong>: 이이가 자부하는 독창적 표현. 리는 무형이기에 통(通)하고, 기는 유형이기에 국(局, 국한)한다. 기국의 리(유행의 측면, 분수리)와 리통의 리(본연의 측면, 리일)는 서로 모순되지 않는다.</li><li><strong>양변설(兩邊說) vs 리기일발설</strong>: 성혼은 논쟁 후반부에서 퇴계의 호발설이 &quot;리와 기가 각각 별도로 존재하다가 각자 발한다&quot;(各自獨發)는 뜻이 아니라, 리와 기가 결합되어 있다가 발현될 때 <strong>무엇이 위주(주리/주기)가 되느냐의 차이</strong>를 표현한 것이라고 절충적으로 재해석하며 이를 &#39;양변설&#39;이라 부름. 그럼에도 이이는 &quot;리발이기수지&quot;라는 표현 자체가 &#39;리선기후&#39;를 함축해 리기불상리에 어긋난다고 보아, 대신 <strong>&#39;리기일발설&#39;</strong>(理氣一發說, 리와 기가 함께 발하되 주리·주기의 구분만 있다는 절충안)을 제안함.</li><li><strong>학자의 세 등급</strong>(이이 8서): 하등급(성현의 글을 읽고 개념·사상체계를 이해하는 학자), 중등급(이해한 후 성찰하여 자기화하는 학자), 상등급(이해와 성찰을 거쳐 실천하는 학자) — 이이는 이 비유를 &quot;말만 듣고 산을 아는 자 / 직접 보고서 산을 아는 자 / 올라가 보고서 산을 아는 자&quot;에 빗대며, 나흠순을 첫째, 퇴계를 둘째, 서경덕을 셋째 등급에 놓음.</li></ul><h2 id="결론" tabindex="-1">결론 <a class="header-anchor" href="#결론" aria-label="Permalink to &quot;결론&quot;">​</a></h2><p>성혼은 끝내 퇴계의 리기호발설(그의 재해석인 &#39;양변설&#39;)을 견지하며, 이이의 &#39;기발리승일도설&#39;과 &quot;칠정이 사단을 포함한다&quot;는 주장은 받아들일 수 없다고 결론짓는다. 이이는 47세 때 「인심도심도설」에서 자신의 입장을 정리한다 — 도의를 실현하기 위해 발현되는 감정(부모에게 효도함, 굶주린 아이를 보고 측은해함 등)이 <strong>도심</strong>이고, 육체를 위해 발현되는 감정(배고플 때 먹으려 함, 추울 때 입으려 함 등)이 <strong>인심</strong>이다. 도심은 순수한 천리이므로 지키고 확충하기만 하면 되지만, 인심은 인욕으로 흐르기 쉬우므로 정밀히 살펴 도심으로 절제해야 하며, 그렇게 되면 인심도 도심으로 거듭날 수 있다. 결국 리발과 기발의 구분은 없다 — <strong>오직 기발만 있을 뿐이며, &#39;리발&#39;이라 부르는 것도 사실은 (맑은) 기의 발현</strong>이라는 것이 이이가 최종적으로 정리한 입장이다.</p>',19)])])}const d=o(e,[["render",a]]);export{p as __pageData,d as default};
